{"id":"group","en":["group"],"target":"flokkur","competitors":[],"sense":"periodic-table-group","senses":[{"id":"periodic-table-group","gloss":"a column of the periodic table and its elements (group 1, group 17, groups 1 and 2, main-group elements)"},{"id":"functional-group","gloss":"an atom or group of atoms within a molecule: a functional group, alkyl group, carbonyl group, hydroxyl group or other substituent"},{"id":"collection","gloss":"an ordinary collection of things or people (the group of three squares in a figure, a group of scientists)"}]},
